            var element = document.RootElement;

            string code = null;
            ResponseInnerError innerError = null;

            foreach (var property in element.EnumerateObject())
            {
                if (property.NameEquals("code"u8))
                {
                    code = property.Value.GetString();
                }
                else if (property.NameEquals("innererror"u8) && property.Value.ValueKind != JsonValueKind.Null)
                {
                    innerError = JsonSerializer.Deserialize(property.Value.GetRawText(), ArmJsonSerializerContext.Default.ResponseInnerError);
                }
            }

            return new ResponseInnerError(code, innerError);
        }

        public override void Write(Utf8JsonWriter writer, ResponseInnerError value, JsonSerializerOptions options)
